5: export default {
6:   mixins: [table],
7:   components: {
8:     zsSearchForm,
9:     zsButton
10:   },
11:   data() {
12:     const data = {
13:       // 删除确认文字
14:       title: false,
15:     }
16:     const hasDesensitizeProp = !!(this && this.$options && this.$options.props && this.$options.props.desensitizeFlag)
17:     if (!hasDesensitizeProp) {
18:       // 表格接口是否加密
19:       data.desensitizeFlag = '1'
20:     }
21:     return data
22:   },
23:   created() {
24:     // 列表页搜索条件缓存
25:     if (this.$store.state.common.cachedSearchParams.get(this.$route.path)) {
26:       this.query = { ...this.queryParams, ...this.$store.state.common.cachedSearchParams.get(this.$route.path) }
27:     } else {
28:       this.$store.dispatch('common/saveSearchParams', { key: this.$route.path, params: this.query })
29:     }
30:     this.init && this.init()
31:   },
32:   computed: {
33:     // 如需缓存除queryParams以外的参数，在页面上重写此变量，要get和set都存在
34:     query: {
35:       get() {
36:         return { ...this.queryParams }
37:       },
38:       set(val) {
39:         if (this.queryParams) {
40:           Object.assign(this.queryParams, val)
41:         }
42:         return val
43:       }
44:     },
45:     tableRowStyle() {
46:       return null
47:     }
48:   },
49:   watch: {
50:     // 需要缓存的参数变化后存入store
51:     query: {
52:       handler: function (newVal, oldVal) {
53:         if (oldVal && !isEqual(newVal, oldVal)) {
54:           this.$store.dispatch('common/saveSearchParams', { key: this.$route.path, params: newVal })
55:         }
56:       },
57:       immediate: true,
58:       deep: true
59:     }
60:   },
61:   methods: {
62:     // 跳转新增页面，如需带参数，在页面上重写此函数
