1: import tableComponents from './tableComponents'
2: import permsMixins from './permsMixins'
3: import router from "@/router/index.js"
4: import { loadSavedTableConfig, buildDisplayColumns } from '@/utils/tableColumnConfig'
5: export default {
6:   mixins: [tableComponents, permsMixins],
7:   data() {
8:     return {
9:       // 表格多选列是否显示
10:       selectable: true,
11:       // 是否显示小计行
12:       showSummary: false,
13:       // 表格多选禁用
14:       multiple: true,
15:       // 总条数
16:       total: 0,
17:       // 选中数组的主键
18:       ids: [],
19:       // 表格数据
20:       tableData: [],
21:       // 列表接口请求类型
22:       apiMethod: 'get',
23:       // 表格接口 loading 变量
24:       loading: false,
25:       // 选种数据数据
26:       selection: [],
27:       displayColumns: [],
28:       originalColumns: [], // 保存原始的列配置
29:       initialized: false,
30:       deleteType: 'v1',
31:       border: false,
32:       showListName: true,
33:       // 列表标题，为空时使用路由 meta.title + '列表'
34:       listName: '',
35:     }
36:   },
37:   created() {
38:     this.initialized = true;
39:     this.$root.$on('table-config-saved', this.onTableConfigSaved);
40:     this.syncDisplayColumns();
41:   },
42:   mounted() {
43:     this.syncDisplayColumns();
44:     this.columnsUnwatch = this.$watch(
45:       () => this.getColumnsSignature(),
46:       () => this.syncDisplayColumns()
47:     );
48:   },
49:   activated() {
50:     this.syncDisplayColumns();
51:   },
52:   beforeDestroy() {
53:     this.$root.$off('table-config-saved', this.onTableConfigSaved);
54:     if (this.columnsUnwatch) {
55:       this.columnsUnwatch();
56:     }
57:   },
58:   watch: {
59:     tableConfig(newConfig) {
60:       if (newConfig && this.originalColumns.length) {
61:         this.applyTableConfig(newConfig);
62:       }
63:     }
64:   },
65:   computed: {
66:     configButton: function () {
67:       return {
68:         label: '自定义列表显示',
69:         attrs: {
70:           type: 'primary',
71:           icon: 'el-icon-setting',
72:         },
73:         listeners: { click: this.openConfigDialog }
74:       }
75:     },
76:     // 表格唯一标识，默认使用moduleName和businessName的组合
77:     tableId() {
78:       return `${this.moduleName}_${this.businessName}`;
79:     },
80:     // 从store获取当前表格的配置
81:     tableConfig() {
82:       return this.$store.getters['table/getTableConfig'](this.tableId)
83:     },
84:     // 列顺序/显隐变化时变更 key，强制 el-table 重建（否则 Element UI 不会按新顺序重排列）
85:     tableColumnsKey() {
86:       return (this.displayColumns || []).map((c) => c.prop).join('|');
87:     },
88:     // 表格行样式，默认不设置；页面可重写此计算属性
89:     tableRowStyle() {
90:       return null
91:     },
92:     // 表格底部合计行数据，默认空；页面可重写
93:     summaryItems() {
94:       return []
95:     },
96:     // 表格底部合计行样式：plain | table
97:     bottomSummaryVariant() {
98:       return 'table'
99:     },
100:     // 表格上方操作按钮配置
101:     addButton: function () {
102:       return {
103:         label: '新增',
104:         attrs: {
105:           type: 'primary',
106:           icon: 'el-icon-plus',
107:           permission: [this.perms.add]
108:         },
109:         listeners: { click: this.handleAdd }
110:       }
111:     },
112:     multiDeleteButton: function () {
113:       return {
114:         label: '删除',
115:         attrs: {
116:           type: 'danger',
117:           icon: 'el-icon-delete',
118:           permission: [this.perms.remove],
119:           multi: this.multiple,
120:           disabled: this.selection.length === 0
121:         },
122:         listeners: { click: this.handleDelete }
123:       }
124:     },
125:     viewButton: function () {
126:       return {
127:         label: this.getLabel,
128:         permissionType: 'view',
129:         function: this.handleView,
130:         permission: false, // 默认情况下列表查看按钮不做权限控制
131:         attrs: {
132:           type: 'primary'
133:         }
134:       }
135:     },
136:     editButton: function () {
137:       return {
138:         label: '编辑',
139:         permissionType: 'edit',
140:         function: this.handleUpdate,
141:         disabled: this.disableButton,
142:         permission: true,
143:         visible: this.showButton,
144:         attrs: {
145:           plain: true
146:         }
147:       }
148:     },
149:     deleteButton: function () {
150:       return {
151:         label: '删除',
152:         permissionType: 'remove',
153:         function: this.handleDelete,
154:         disabled: this.disableButton,
155:         permission: true,
156:         attrs: {
157:           type: 'danger',
158:           plain: true
159:         }
160:       }
161:     },
162:     operationButtons: function () {
163:       return [
164:         this.addButton,
165:         this.multiDeleteButton
166:       ]
167:     },
168:     // 表格操作列按钮配置
169:     buttons: function () {
170:       return [
171:         this.viewButton,
172:         this.editButton,
173:         this.deleteButton
174:       ]
175:     },
176:     formItems: function () {
177:       return []
178:     },
179:     // 列表接口地址最后一级
180:     apiSuffix: function () {
181:       return 'page'
182:     },
183:   },
184:   methods: {
185:     shouldDeferListForRegionTree() {
186:       if (this.value) return false
187:       if (!this.$store.getters.showRegionTreePanel) return false
188:       return !!(this.$options.components && this.$options.components.RegionTreeLayout)
189:     },
190:     init() {
191:       this.initDict && this.initDict()
192:       if (this.shouldDeferListForRegionTree()) {
193:         this._deferRegionTreeList = true
194:         return
195:       }
196:       this.getList()
197:     },
198:     // 搜索方法
199:     handleQuery() {
200:       this.queryParams.pageNum = 1
201:       this.getList()
202:     },
203:     // 重置搜索条件方法
204:     resetQuery() {
205:       this.queryParams = this.$options.data().queryParams
206:       this.handleQuery()
207:     },
208:     getColumnsSignature() {
209:       return (this.columns || [])
210:         .map((col) => `${col.prop || ''}:${col.sortOrder || ''}`)
211:         .join('|');
212:     },
213:     syncDisplayColumns() {
214:       const cols = this.columns;
215:       if (!Array.isArray(cols) || !cols.length) {
216:         return;
217:       }
218:       this.originalColumns = cols.map((col) => ({ ...col }));
219:       this.loadTableConfigFromStore();
220:     },
221:     applyTableConfig(config) {
222:       if (!this.originalColumns.length) return;
223:       this.displayColumns = buildDisplayColumns(this.originalColumns, config);
224:     },
225:     onTableConfigSaved({ tableId, config }) {
226:       if (tableId !== this.tableId) return;
227:       this.applyTableConfig(config);
228:     },
229:     // 从store加载配置
230:     loadTableConfigFromStore() {
231:       const savedConfig = loadSavedTableConfig(this.$store, this.tableId);
232:       if (savedConfig) {
233:         this.applyTableConfig(savedConfig);
234:       } else {
235:         this.displayColumns = this.originalColumns.map((col) => ({ ...col }));
236:       }
237:     },
238:     openConfigDialog() {
239:       // 直接发送全局事件，打开配置对话框
240:       this.$root.$emit('open-table-config', {
241:         tableId: this.tableId,
242:         columns: this.columns
243:       })
244:     },
245:     // 删除确认弹窗
246:     confirm({ message = '是否确认删除已选的数据项?', title = '警告', confirmButtonText = '确定', cancelButtonText = '取消', type = 'warning' }) {
247:       return this.$confirm(message, title, {
248:         confirmButtonText,
249:         cancelButtonText,
250:         type
251:       })
252:     },
253:     // 表格选择列配置
254:     isSelectable(row) {
255:       return row.bizState == '0' || !row.bizState
256:     },
257:     // 操作列按钮禁用条件
258:     disableButton(row) {
259:       return typeof row.bizState !== 'undefined' && row.bizState != '0'
260:     },
261:     // 如需配置额外的查询参数，在页面上重写此函数
262:     getQueryParams() {
263:       return this.queryParams
264:     },
265:     // 列表接口回调函数，如需执行其他逻辑，在页面上重写此函数
