116:   computed: {
117:     isSingleLine() {
118:       return this.computedFormItems.length <= this.COLUMN_SPAN.ITEMS_PER_ROW
119:     },
120:     computedFormItems() {
121:       return this.formItems
122:         .filter((item) => item.type === 'region-select' ? this.isCityLevel : true)
123:         .map((item) => {
124:           if (item.type === 'select' && item.model === 'bizState') {
125:             const attrs = item.attrs || {}
126:             const isMultiple = Object.prototype.hasOwnProperty.call(attrs, 'multiple') ? attrs.multiple : false
127:             const nextAttrs = {
128:               ...attrs,
129:               multiple: isMultiple
130:             }
131: 
132:             if (isMultiple) {
133:               nextAttrs.collapseTags = Object.prototype.hasOwnProperty.call(attrs, 'collapseTags') ? attrs.collapseTags : true
134:             } else {
135:               delete nextAttrs.collapseTags
